import{_ as o,r as n,o as d,c as r,e as a,a as c,s as p}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Data Table 字段 - October CMS - 3.x","titleTemplate":false,"description":"表单小部件","frontmatter":{"subtitle":"表单小部件","shortname":"Data Table"},"headers":[{"level":4,"title":"列配置","slug":"列配置","link":"#列配置","children":[]},{"level":4,"title":"列验证","slug":"列验证","link":"#列验证","children":[]},{"level":4,"title":"AJAX 处理程序","slug":"ajax-处理程序","link":"#ajax-处理程序","children":[]}],"relativePath":"3.x/zh-cn/element/form/widget-datatable.md","filePath":"3.x/zh-cn/element/form/widget-datatable.md"}'),l={name:"3.x/zh-cn/element/form/widget-datatable.md"};function i(u,t,g,k,m,h){const e=n("pre-heading"),s=n("post-heading");return d(),r("div",null,[a(e),t[0]||(t[0]=c("h1",null,"Data Table 字段",-1)),a(s),t[1]||(t[1]=p(`<p><code>datatable</code> - 渲染一个可编辑的记录表格，以网格形式显示。单元格内容可以直接在网格中编辑，允许管理多行多列的信息。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">data</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datatable
    <span class="token key atrule">adding</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">deleting</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">columns</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
    <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">searching</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><div class="custom-block tip"><p>要将此字段与模型一起使用，该字段应在 <a href="./../../extend/system/models.html">jsonable 属性</a>中定义，或使用任何可以处理数组存储的方式。</p></div><p>以下<a href="./../form-fields.html">字段属性</a>受支持且常用。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示表单字段时使用的名称。</td></tr><tr><td><strong>default</strong></td><td>指定默认字符串值，可选。</td></tr><tr><td><strong>comment</strong></td><td>在字段下方放置描述性注释。</td></tr><tr><td><strong>adding</strong></td><td>允许向数据表添加记录。默认值：<code>true</code>。</td></tr><tr><td><strong>btnAddRowLabel</strong></td><td>为&quot;在上方添加行&quot;按钮定义自定义标签。</td></tr><tr><td><strong>btnAddRowBelowLabel</strong></td><td>为&quot;在下方添加行&quot;按钮定义自定义标签。</td></tr><tr><td><strong>btnDeleteRowLabel</strong></td><td>为&quot;删除行&quot;按钮定义自定义标签。</td></tr><tr><td><strong>columns</strong></td><td>表示数据表列配置的数组。请参阅下方的<em>列配置</em>部分。</td></tr><tr><td><strong>deleting</strong></td><td>允许从数据表中删除记录。默认值：<code>true</code>。</td></tr><tr><td><strong>dynamicHeight</strong></td><td>如果为 <code>true</code>，数据表的高度将根据添加的记录扩展或收缩，最大不超过 <code>height</code> 配置值定义的大小。默认值：<code>false</code>。</td></tr><tr><td><strong>fieldName</strong></td><td>定义在数据表发送的 POST 数据中使用的自定义字段名称。留空以使用默认字段别名。</td></tr><tr><td><strong>height</strong></td><td>数据表的高度，以像素为单位。如果设置为 <code>false</code>，数据表将拉伸以适应字段容器。</td></tr><tr><td><strong>keyFrom</strong></td><td>用于标识每条记录的数据属性。通常应设置为 <code>id</code>。仅支持整数值。</td></tr><tr><td><strong>postbackHandlerName</strong></td><td>指定数据表内容将随之发送的 AJAX 处理程序名称。当设置为 <code>null</code>（默认值）时，处理程序名称将从包含数据表的表单所使用的请求名称中自动检测。建议保持为 <code>null</code>。</td></tr><tr><td><strong>recordsPerPage</strong></td><td>每页显示的记录数。如果设置为 <code>false</code>，将禁用分页。</td></tr><tr><td><strong>searching</strong></td><td>允许通过搜索框搜索记录。默认值：<code>false</code>。</td></tr><tr><td><strong>toolbar</strong></td><td>表示数据表工具栏配置的数组。</td></tr></tbody></table></div><h4 id="列配置"><a href="#列配置" class="header-anchor">#</a> 列配置</h4><p>数据表小部件允许通过 <code>columns</code> 配置变量以数组形式指定列。每列应使用字段名称作为键，并使用以下配置变量来设置字段。</p><p>示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">id</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> ID
        <span class="token key atrule">validation</span><span class="token punctuation">:</span>
            <span class="token key atrule">integer</span><span class="token punctuation">:</span>
                <span class="token key atrule">message</span><span class="token punctuation">:</span> Please enter a number
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> string
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Name
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>此列单元格的输入类型。必须是以下之一：<code>string</code>、<code>checkbox</code>、<code>dropdown</code> 或 <code>autocomplete</code>。</td></tr><tr><td><strong>options</strong></td><td>仅用于 <code>dropdown</code> 和 <code>autocomplete</code> 列。数组键定义选项值，数组值定义选项标签。请参阅下方的 AJAX 处理程序部分。</td></tr><tr><td><strong>readOnly</strong></td><td>此列是否为只读。默认值：<code>false</code>。</td></tr><tr><td><strong>title</strong></td><td>定义列的标题。</td></tr><tr><td><strong>validation</strong></td><td>指定列单元格内容验证的数组。请参阅下方的<em>列验证</em>部分。</td></tr><tr><td><strong>width</strong></td><td>定义列的宽度，以像素为单位。</td></tr></tbody></table></div><h4 id="列验证"><a href="#列验证" class="header-anchor">#</a> 列验证</h4><p>列单元格可以根据以下类型的验证进行验证。验证应指定为数组，验证类型用作键，可选的消息通过该验证的 <code>message</code> 属性指定。</p><div class="table"><table tabindex="0"><thead><tr><th>验证</th><th>描述</th></tr></thead><tbody><tr><td><strong>float</strong></td><td>验证数据是否为浮点数。可提供可选的布尔值 <code>allowNegative</code> 属性，允许负浮点数。</td></tr><tr><td><strong>integer</strong></td><td>验证数据是否为整数。可提供可选的布尔值 <code>allowNegative</code> 属性，允许负整数。</td></tr><tr><td><strong>length</strong></td><td>验证数据是否为特定长度。必须提供整数 <code>min</code> 和 <code>max</code> 属性，表示必须输入的最少和最多字符数。</td></tr><tr><td><strong>regex</strong></td><td>根据正则表达式验证数据。必须提供字符串 <code>pattern</code> 属性，定义用于测试数据的正则表达式。</td></tr><tr><td><strong>required</strong></td><td>验证在保存前必须输入数据。</td></tr></tbody></table></div><h4 id="ajax-处理程序"><a href="#ajax-处理程序" class="header-anchor">#</a> AJAX 处理程序</h4><p>对于 <code>dropdown</code> 或 <code>autocomplete</code> 类型的列，可用选项列表可以通过模型中定义的 AJAX 处理程序提供。</p><p>处理程序必须遵循命名约定 <code>getFieldNameDataTableOptions()</code>，其中 <code>FieldName</code> 匹配表单配置中定义的字段名称。</p><p>该方法应返回一个关联数组，其中数组键用作存储值，数组值用作数据表中的显示标签。</p><p>例如，对于名为 <strong>country</strong> 的字段，使用 <code>getCountryDataTableOptions</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getCountryDataTableOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Country</span><span class="token operator">::</span><span class="token function">pluck</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;code&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这将自动填充 DataTable 中 <code>country</code> 字段的选项。</p>`,20))])}const f=o(l,[["render",i]]);export{y as __pageData,f as default};
